-- Builds the slot table.
function FurorHud_Slots()
  local slots, slot_of = {}, {}
  for index, layer in ipairs(furor_hud.LAYERS) do
    layer.first = #slots + 1
    slot_of[layer.kind] = {[0] = {}, [1] = {}}
    for side = 0, 1 do
      for k = 1, layer.per_side do
        slots[#slots + 1] = {layer = layer.id, instance = side * layer.per_side + k - 1, side = side, kind = layer.kind,
          layer_index = index}
        slot_of[layer.kind][side][k] = #slots
      end
    end
    layer.last = #slots
  end
  furor_hud.slots, furor_hud.slot_of = slots, slot_of
end

-- slot -> layer, instance, side
function FurorHud_Slot(slot)
  local s = furor_hud.slots[slot]
  return s.layer, s.instance, s.side
end

function FurorHud_Log(...)
  if Furor.hud.LOGS >= Furor.hud.MAX_LOGS or type(funcLuaCommand) ~= "function" then
    return
  end
  Furor.hud.LOGS = Furor.hud.LOGS + 1
  Furor.hud.logger = Furor.hud.logger or VRFW.logger.new("FUROR")
  Furor.hud.logger.debug(...)
end

-- Reads the value of a side (0 own, 1 rival).
function FurorHud_Value(side)
  if type(funcLuaCommand) ~= "function" then
    return nil
  end
  local ok, has, ratio, phase, _, _, _, full = pcall(funcLuaCommand, Furor.hud.CMD, Furor.hud.KEY, side == 0 and -1 or -2)
  if not ok or has ~= true or type(ratio) ~= "number" then
    return nil
  end
  return math.max(0, math.min(1, ratio)), phase == 1, full == 1
end

-- Reads the furor button.
function FurorHud_Button()
  if type(funcLuaCommand) ~= "function" then
    return
  end
  local down = false
  for _, ctrl in ipairs(Furor.hud.CTRLS) do
    local ok, on = pcall(funcLuaCommand, furor_hud.CHECK_INPUT, ctrl, Furor.hud.BUTTON)
    if ok and on == true then
      down = true
    end
  end
  if down and not furor_hud.button_was then
    local ok, started = pcall(funcLuaCommand, Furor.hud.START, Furor.hud.KEY, -1)
    FurorHud_Log("button", ok and started == true and "phase started" or "not full")
  end
  furor_hud.button_was = down
end

function FurorHud_Global(layer, index, node)
  local x, y = VRFW.host.menu_command(furor_hud.GLOBAL_POS, layer, index, node)
  if type(x) ~= "number" or type(y) ~= "number" then
    return nil
  end
  return x, y
end

-- Reads the keeper bar locators' screen positions once per frame.
function FurorHud_Locators()
  if furor_hud.locators_tick ~= furor_hud.tick then
    furor_hud.locators_tick = furor_hud.tick
    local own_x, own_y = FurorHud_Global(furor_hud.KEEPER_BARS, 0, furor_hud.LOCATORS[1])
    local rival_x, rival_y = FurorHud_Global(furor_hud.KEEPER_BARS, 0, furor_hud.LOCATORS[2])
    furor_hud.locators = (own_x ~= nil and rival_x ~= nil) and {own_x, own_y, rival_x, rival_y} or nil
  end
  local l = furor_hud.locators
  if l == nil then
    return nil
  end
  return l[1], l[2], l[3], l[4]
end

-- Measures a slot's mapping.
function FurorHud_Probe(slot)
  if furor_hud.mapping[slot] ~= nil then
    return furor_hud.mapping[slot] ~= false
  end
  local layer, i = FurorHud_Slot(slot)
  local p = furor_hud.probe[slot]
  if p == nil then
    furor_hud.probe[slot] = {stage = 1, wait = Furor.hud.PROBE_WAIT}
    VRFW.host.menu_command(furor_hud.SET_SCALE, layer, 1, 1, 1, i)
    VRFW.host.menu_command(furor_hud.SET_POS, layer, 0, 0, 0, i)
    return false
  end
  if p.wait > 0 then
    p.wait = p.wait - 1
    return false
  end
  local x, y = FurorHud_Global(layer, i, furor_hud.DRAW_NODE)
  if x == nil then
    furor_hud.mapping[slot] = false
    FurorHud_Log("slot", slot, "no global position for the frame node: hidden")
    return false
  end
  local step = Furor.hud.PROBE_STEP
  if p.stage == 1 then
    p.x1, p.y1, p.stage, p.wait = x, y, 2, Furor.hud.PROBE_WAIT
    VRFW.host.menu_command(furor_hud.SET_POS, layer, step, step, 0, i)
    return false
  end
  if p.stage == 2 then
    p.x2, p.y2, p.stage, p.wait = x, y, 3, Furor.hud.PROBE_WAIT
    VRFW.host.menu_command(furor_hud.SET_POS, layer, 0, 0, 0, i)
    VRFW.host.menu_command(furor_hud.SET_SCALE, layer, 2, 2, 1, i)
    return false
  end
  local unit_x, unit_y = (p.x2 - p.x1) / step, (p.y2 - p.y1) / step
  if math.abs(unit_x) < 0.05 or math.abs(unit_y) < 0.05 then
    furor_hud.mapping[slot] = false
    FurorHud_Log("slot", slot, "position does not move the frame node: hidden")
    return false
  end
  -- An open animation (the scoreboard's, the gauge's) still moving the node shows as x and y units that differ.
  local tries = (furor_hud.tries[slot] or 0) + 1
  furor_hud.tries[slot] = tries
  if math.abs(unit_x - unit_y) > Furor.hud.UNIT_TOLERANCE * math.max(math.abs(unit_x), math.abs(unit_y))
      and tries < Furor.hud.PROBE_TRIES then
    FurorHud_Log("slot", slot, "probe", tries, "units differ", string.format("%.3f %.3f", unit_x, unit_y), "measuring again")
    furor_hud.probe[slot] = nil
    return false
  end
  local node_x, node_y = x - p.x1, y - p.y1
  furor_hud.mapping[slot] = {unit_x = unit_x, unit_y = unit_y, node_x = node_x, node_y = node_y,
    origin_x = p.x1 - node_x, origin_y = p.y1 - node_y}
  if slot <= 2 then
    FurorHud_Log("slot", slot, "frame node point", string.format("%.1f %.1f", node_x / unit_x, node_y / unit_y))
    FurorHud_Log("slot", slot, "mapping unit", string.format("%.3f %.3f", unit_x, unit_y), "origin",
      string.format("%.1f %.1f", p.x1 - node_x, p.y1 - node_y))
  end
  return true
end

-- Computes a slot's local position and scale for a quad `width` x `height` layout units whose crest-side end lies on the locator.
function FurorHud_Target(side, width, height, map, inner, rise)
  local own_x, own_y, rival_x, rival_y = FurorHud_Locators()
  if own_x == nil then
    return nil
  end
  local board_x = (rival_x - own_x) / Furor.hud.LOCATOR_SPAN
  if math.abs(board_x) < 0.05 then
    return nil
  end
  local board_y = board_x * map.unit_y / map.unit_x
  local top = Furor.hud.BAR_MIDDLE + (rise or 0) + height / 2
  local target_x, target_y
  inner = Furor.hud.BAR_INNER + (inner or 0)
  if side == 0 then
    target_x = own_x + (inner - width) * board_x
    target_y = own_y + top * board_y
  else
    target_x = rival_x - inner * board_x
    target_y = rival_y + top * board_y
  end
  local sx = width * board_x / (map.unit_x * furor_hud.SOURCE_W)
  local sy = height * board_y / (map.unit_y * furor_hud.SOURCE_H)
  local px = (target_x - map.origin_x) / map.unit_x - sx * furor_hud.SOURCE_X
  local py = (target_y - map.origin_y) / map.unit_y - sy * furor_hud.SOURCE_Y
  return px, py, sx, sy
end

-- Places a slot.
function FurorHud_Place(slot, look)
  local layer, i, side = FurorHud_Slot(slot)
  local map = furor_hud.mapping[slot]
  local place = furor_hud.place[slot]
  if not look.moving then
    if place and place.wait > 0 then
      place.wait = place.wait - 1
      return place.settled
    end
    if place then
      local x, y = FurorHud_Global(layer, i, furor_hud.DRAW_NODE)
      if x ~= nil then
        local origin_x = x - map.unit_x * place.px - place.sx * map.node_x
        local origin_y = y - map.unit_y * place.py - place.sy * map.node_y
        local error_x, error_y = origin_x - map.origin_x, origin_y - map.origin_y
        if math.abs(error_x) <= Furor.hud.SNAP and math.abs(error_y) <= Furor.hud.SNAP then
          place.settled = true
        end
        if math.abs(error_x) > 0.5 or math.abs(error_y) > 0.5 then
          map.origin_x, map.origin_y = origin_x, origin_y
        end
      end
    end
  end
  local px, py, sx, sy = FurorHud_Target(side, look.width, look.height, map, look.inner, look.rise)
  if px == nil then
    return false
  end
  if not furor_hud.logged[slot] and slot <= 2 then
    furor_hud.logged[slot] = true
    local own_x, own_y, rival_x, rival_y = FurorHud_Locators()
    FurorHud_Log("slot", slot, "locators", string.format("%.1f %.1f / %.1f %.1f", own_x or 0, own_y or 0, rival_x or 0, rival_y or 0))
    FurorHud_Log("slot", slot, "size", string.format("%.1f %.1f", look.width, look.height), "pos scale",
      string.format("%.1f %.1f / %.3f %.3f", px, py, sx, sy))
  end
  if place == nil or math.abs(place.px - px) > 0.05 or math.abs(place.py - py) > 0.05 or math.abs(place.sx - sx) > 0.0005
      or math.abs(place.sy - sy) > 0.0005 then
    VRFW.host.menu_command(furor_hud.SET_SCALE, layer, sx, sy, 1, i)
    VRFW.host.menu_command(furor_hud.SET_POS, layer, px, py, 0, i)
    place = {px = px, py = py, sx = sx, sy = sy, wait = look.moving and 0 or Furor.hud.SETTLE,
      settled = look.moving or (place ~= nil and place.settled)}
    furor_hud.place[slot] = place
  end
  return place.settled
end

function FurorHud_Hide(slot)
  if furor_hud.shown[slot] then
    local layer, i = FurorHud_Slot(slot)
    furor_hud.shown[slot] = false
    VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, layer, i, false)
  end
  furor_hud.lit[slot], furor_hud.alpha[slot] = nil, nil
end

function FurorHud_Prepare(slot)
  local layer, i = FurorHud_Slot(slot)
  furor_hud.ready[slot] = true
  furor_hud.shown[slot] = false
  furor_hud.sprite[slot] = nil
  VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, layer, i, false)    -- hidden until placed
  FurorHud_Fill(slot)
end

-- Fills a slot's look.
function FurorHud_Fill(slot)
  FurorHud_HideMeshes(slot)
  local layer, i = FurorHud_Slot(slot)
  VRFW.host.menu_command(furor_hud.MESH_VISIBLE, layer, furor_hud.MESH_FRAME, furor_hud.lit[slot] ~= false, i)
  furor_hud.alpha[slot] = nil
  if furor_hud.shown[slot] and not furor_hud.fill_logged[slot] and slot <= 2 then
    furor_hud.fill_logged[slot] = true
    FurorHud_Log("slot", slot, "frame quad drawn after the show")
  end
end

function FurorHud_HideMeshes(slot)
  local layer, i = FurorHud_Slot(slot)
  VRFW.host.menu_command(furor_hud.MESH_VISIBLE, layer, furor_hud.MESH_FILL, false, i)
  VRFW.host.menu_command(furor_hud.MESH_VISIBLE, layer, furor_hud.MESH_LABEL, false, i)
  VRFW.host.menu_command(furor_hud.MESH_VISIBLE, layer, furor_hud.MESH_TRAIL, false, i)
end

-- a shown slot's frame quad drawn or not (only on a change)
function FurorHud_Lit(slot, on)
  if furor_hud.lit[slot] ~= on then
    local layer, i = FurorHud_Slot(slot)
    furor_hud.lit[slot] = on
    VRFW.host.menu_command(furor_hud.MESH_VISIBLE, layer, furor_hud.MESH_FRAME, on, i)
  end
end

-- a shown slot's alpha (only on a change)
function FurorHud_Alpha(slot, alpha)
  if furor_hud.alpha[slot] == nil or math.abs(furor_hud.alpha[slot] - alpha) > 0.004 then
    local layer, i = FurorHud_Slot(slot)
    furor_hud.alpha[slot] = alpha
    VRFW.host.menu_command(furor_hud.PRIM_ALPHA, layer, i, furor_hud.MESH_FRAME, alpha)
  end
end

-- Returns whether the furor atlases (their own G4TX files, research/mods/FootballReforged/modules/Furor/_tools/furor_gauge_draw.py) are in memory.
function FurorHud_TextureReady()
  if furor_hud.texture == 0 then
    for _, atlas in ipairs(Furor.hud.ATLASES) do
      VRFW.host.menu_command(furor_hud.LOAD_TEXTURE, atlas.path)
    end
    furor_hud.texture = 1
    return false
  end
  if furor_hud.texture == 1 and type(funcLuaCommand) == "function" then
    local all = true
    for _, atlas in ipairs(Furor.hud.ATLASES) do
      local ok, loading = pcall(funcLuaCommand, furor_hud.TEXTURE_LOADING, atlas.id)
      if not ok or loading then
        all = false
      end
    end
    if all then
      furor_hud.texture = 2
      FurorHud_Log("atlases in", #Furor.hud.ATLASES)
    end
  end
  return furor_hud.texture == 2
end

-- swaps a slot's sprite (of the atlas `atlas`) only on a change
function FurorHud_Sprite(slot, sprite, atlas)
  if furor_hud.debug then
    return                                    -- debug: the plain retail gauge stays
  end
  if furor_hud.sprite[slot] ~= sprite then
    local layer, i = FurorHud_Slot(slot)
    furor_hud.sprite[slot] = sprite
    VRFW.host.menu_command(558735651 --[[swap texture]], layer, atlas, sprite, furor_hud.TEXTURE_SLOT, 0, i)
  end
end

-- Computes this frame's seconds.
function FurorHud_Clock()
  local dt = 1 / 60
  if type(funcLuaCommand) == "function" then
    local ok, s = pcall(funcLuaCommand, Furor.hud.FRAME_SECONDS)
    if ok and type(s) == "number" and s > 0 and s < 0.25 then
      dt = s
    end
  end
  furor_hud.dt = dt
  furor_hud.clock = furor_hud.clock + dt
end

-- Returns the ratio a side draws this frame.
function FurorHud_Drawn(side, ratio)
  local drawn = furor_hud.drawn[side]
  if drawn == nil then
    furor_hud.drawn[side] = ratio
    return ratio
  end
  drawn = drawn + (ratio - drawn) * (1 - math.exp(-furor_hud.dt / Furor.hud.EASE_SECONDS))
  if math.abs(ratio - drawn) < 0.0005 then
    drawn = ratio
  end
  furor_hud.drawn[side] = drawn
  return drawn
end

-- 0 -> 1 -> 0 over u = 0..1 (Strikers' linear TRAN keys at 0, 30 and 60)
function FurorHud_Pulse(u)
  return 1 - math.abs(2 * u - 1)
end

function FurorHud_Looks(side, ratio, phase, full)
  local st = furor_hud.sides[side]
  local sprites = Furor.hud.SPRITES[side]
  local atlas = Furor.hud.ATLAS_OF
  local sizes = Furor.hud.SIZES
  local reach = Furor.hud.REACH[side]
  local slot_of = furor_hud.slot_of
  local frame = furor_hud.clock * Furor.hud.FPS
  local looks = {}
  local off = {off = true}
  looks[slot_of.trough[side][1]] = {sprite = sprites.trough, atlas = atlas.trough, width = sizes.trough[1],
    height = sizes.trough[2], inner = reach.trough, rise = Furor.hud.RISE[side].trough}
  local maxed = full and not phase and ratio >= 0.995
  if maxed then
    st.full_since = st.full_since or furor_hud.clock
  else
    st.full_since = nil
  end
  local delta = ratio - (st.last or ratio)
  st.last = ratio
  local share = maxed and 1 or ratio
  local cut = share * Furor.hud.STEPS
  local base, glow, stripes = off, off, off
  if cut >= 0.05 then
    local step = math.max(1, math.min(Furor.hud.STEPS, math.ceil(cut - 1e-6)))
    local width, height = sizes.fill[1] * math.min(1, share), sizes.fill[2]
    base = {sprite = sprites.base[step], atlas = atlas.base, width = width, height = height}
    local pulse = Furor.hud.GLOW_ALPHA * FurorHud_Pulse((frame % Furor.hud.PULSE_FRAMES) / Furor.hud.PULSE_FRAMES)
    if pulse > 0.004 then
      glow = {sprite = sprites.glow[step], atlas = atlas.glow, width = width, height = height, alpha = pulse}
    end
    local look = nil
    if not maxed and delta > 1e-6 then
      look = "up"
    elseif not maxed and delta < -1e-6 then
      look = "down"
    end
    if look ~= nil then
      local frames = sprites[look]
      local f = math.floor(frame / Furor.hud.STRIPE_FRAMES) % #frames + 1
      stripes = {sprite = frames[f][step], atlas = atlas[look], width = width, height = height,
        alpha = Furor.hud.STRIPE_ALPHA}
    end
  end
  looks[slot_of.base[side][1]] = base
  looks[slot_of.glow[side][1]] = glow
  looks[slot_of.stripes[side][1]] = stripes
  looks[slot_of.max[side][1]] = off
  for k = 1, Furor.hud.SPARK_SLOTS do
    looks[slot_of.spark[side][k]] = off
  end
  if maxed then
    local g = ((furor_hud.clock - st.full_since) * Furor.hud.FPS) % Furor.hud.PULSE_FRAMES
    looks[slot_of.max[side][1]] = {sprite = sprites.max, atlas = atlas.max, width = sizes.max[1], height = sizes.max[2],
      inner = reach.max, rise = Furor.hud.RISE[side].max, alpha = FurorHud_Pulse(g / Furor.hud.PULSE_FRAMES)}
    for _, spark in ipairs(Furor.hud.SPARKS) do
      if g >= spark.start and g < spark.start + Furor.hud.SPARK_LIFE then
        local u = (g - spark.start) / Furor.hud.SPARK_LIFE
        local scale = Furor.hud.SPARK_SCALE + (1 - Furor.hud.SPARK_SCALE) * u
        local w, h = sizes.spark[1] * scale, sizes.spark[2] * scale
        -- the centre past the flames' crest-side end and above their middle (texture pixels -> layout units)
        local past = (spark.x0 + (spark.x1 - spark.x0) * u - Furor.hud.MAX_TO_CREST[side]) * Furor.hud.UNIT
        local above = (Furor.hud.MAX_MIDDLE - (spark.y0 + (spark.y1 - spark.y0) * u)) * Furor.hud.UNIT
        looks[slot_of.spark[side][spark.slot]] = {sprite = sprites.spark, atlas = atlas.spark, width = w, height = h,
          inner = past + w / 2, rise = above, alpha = 1 - u, moving = true}
      end
    end
  end
  return looks
end

-- the step's state, one line per change (why it stops early, or "drawing")
function FurorHud_Why(why)
  if furor_hud.why ~= why then
    furor_hud.why = why
    FurorHud_Log("step", why)
  end
end

function FurorHud_HideAll()
  if furor_hud.slots ~= nil then
    for slot = 1, #furor_hud.slots do
      FurorHud_Hide(slot)
    end
  end
  FurorHud_PromptHide()
end

-- Runs when the glyph's layer opened (the game's call, with the scoreboard).
function FurorHud_PromptOpened()
  local P = furor_hud.PROMPT
  furor_hud.prompt = {}
  VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, P.LAYER, 0, false)
  local ok, text = pcall(funcLuaCommand, P.TEXT_GET, P.TEXT_ROW)
  if not ok or type(text) ~= "string" or text == "" then
    FurorHud_Log("prompt: no text row")
    return
  end
  VRFW.host.menu_command(P.SET_STYLE, P.LAYER, 0, P.TEXT_NODE, P.STYLE)
  VRFW.host.menu_command(P.SET_TEXT, P.LAYER, P.TEXT_NODE, text, 0)
  VRFW.host.menu_command(furor_hud.SET_SCALE, P.LAYER, Furor.hud.PROMPT_SCALE, Furor.hud.PROMPT_SCALE, 1, 0)
  VRFW.host.menu_command(furor_hud.SET_POS, P.LAYER, 0, 0, 0, 0)
  furor_hud.prompt = {open = true, px = 0, py = 0, wait = Furor.hud.SETTLE, tries = 0}
end

function FurorHud_PromptHide()
  local p = furor_hud.prompt
  if p.shown then
    p.shown = false
    VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, furor_hud.PROMPT.LAYER, 0, false)
  end
end

-- Makes the prompt follow the own trough.
function FurorHud_Prompt()
  local p = furor_hud.prompt
  if not p.open then
    return
  end
  local trough = furor_hud.slot_of.trough[0][1]
  local map = furor_hud.mapping[trough]
  local own_x, own_y, rival_x = FurorHud_Locators()
  if not furor_hud.shown[trough] or not map or own_x == nil then
    FurorHud_PromptHide()
    return
  end
  local board_x = (rival_x - own_x) / Furor.hud.LOCATOR_SPAN
  local x = own_x + Furor.hud.PROMPT_INNER * board_x
  local y = own_y + Furor.hud.BAR_MIDDLE * board_x * map.unit_y / map.unit_x
  if p.settled and math.abs(x - p.x) <= 0.5 and math.abs(y - p.y) <= 0.5 then
    if not p.shown then
      p.shown = true
      VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, furor_hud.PROMPT.LAYER, 0, true)
    end
    return
  end
  if p.settled then
    p.settled, p.tries = false, 0
  end
  if p.wait > 0 then
    p.wait = p.wait - 1
    return
  end
  local at_x, at_y = FurorHud_Global(furor_hud.PROMPT.LAYER, 0, furor_hud.PROMPT.ORIGIN_NODE)
  if at_x == nil or p.tries >= Furor.hud.PROMPT_TRIES then
    FurorHud_PromptHide()
    return
  end
  local error_x, error_y = x - at_x, y - at_y
  if math.abs(error_x) <= 0.5 and math.abs(error_y) <= 0.5 then
    p.settled, p.x, p.y = true, x, y
    return
  end
  p.tries = p.tries + 1
  p.px, p.py = p.px + error_x / map.unit_x, p.py + error_y / map.unit_y
  p.wait = Furor.hud.SETTLE
  VRFW.host.menu_command(furor_hud.SET_POS, furor_hud.PROMPT.LAYER, p.px, p.py, 0, 0)
end

function FurorHud_Step()
  if not Furor.hud.ENABLED or Furor.hud.SPRITES == nil or VRFW.host.menu_command(2640875187, furor_hud.KEEPER_BARS, 0) ~= true then
    FurorHud_Why("keeper bar layer closed")
    FurorHud_HideAll()
    return
  end
  if furor_hud.slots == nil then
    FurorHud_Slots()
  end
  furor_hud.tick = furor_hud.tick + 1
  FurorHud_Clock()
  if furor_hud.debug == nil and type(funcLuaCommand) == "function" then
    local ok, debug = pcall(funcLuaCommand, Furor.hud.DEBUG_CMD)
    furor_hud.debug = ok and debug == 1
    if furor_hud.debug then
      FurorHud_Log("debug: plain retail gauges at every slot, the fire full")
    end
  end
  local looks = {}
  local any = false
  for side = 0, 1 do
    local ratio, phase, full = FurorHud_Value(side)
    if ratio ~= nil and furor_hud.debug then
      ratio, phase, full = 1, false, true
    end
    if ratio ~= nil then
      any = true
      for slot, look in pairs(FurorHud_Looks(side, FurorHud_Drawn(side, ratio), phase, full)) do
        looks[slot] = look
      end
      if side == 0 then
        FurorHud_Button()
      end
    end
  end
  if not any then
    FurorHud_Why("no gauge answer (no match / module off)")
    furor_hud.drawn = {}
    furor_hud.sides = {[0] = {}, [1] = {}}
    FurorHud_HideAll()
    return
  end
  for index, layer in ipairs(furor_hud.LAYERS) do
    if VRFW.host.menu_command(2640875187, layer.id) ~= true then
      for slot = layer.first, layer.last do
        furor_hud.ready[slot], furor_hud.shown[slot], furor_hud.sprite[slot] = false, false, nil
        furor_hud.mapping[slot], furor_hud.probe[slot], furor_hud.place[slot] = nil, nil, nil
        furor_hud.tries[slot], furor_hud.lit[slot], furor_hud.alpha[slot] = nil, nil, nil
      end
      furor_hud.init[index] = false
      VRFW.host.menu_command(2152386330, layer.id)
      FurorHud_Why("opening layer " .. index)
      return
    end
    if VRFW.host.menu_command(3057768039, layer.id) == true then
      FurorHud_Why("layer " .. index .. " loading")
      return
    end
    if not furor_hud.init[index] then
      furor_hud.init[index] = true
      for slot = layer.first, layer.last do
        local _, i = FurorHud_Slot(slot)
        VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, layer.id, i, false)
        FurorHud_HideMeshes(slot)
        furor_hud.shown[slot] = false
      end
      FurorHud_Log("layer", index, "open: instances hidden")
    end
  end
  if not FurorHud_TextureReady() then
    FurorHud_Why("furor atlas loading")
    FurorHud_HideAll()
    return
  end
  FurorHud_Why("drawing")
  for slot = 1, #furor_hud.slots do
    local look = looks[slot]
    if look == nil then
      FurorHud_Hide(slot)
    else
      if not furor_hud.ready[slot] then
        FurorHud_Prepare(slot)
      end
      if look.off then
        FurorHud_Probe(slot)                  -- measured ahead, so it draws on its first frame
        if furor_hud.shown[slot] then
          FurorHud_Lit(slot, false)
        end
      else
        FurorHud_Sprite(slot, look.sprite, look.atlas)
        if FurorHud_Probe(slot) and FurorHud_Place(slot, look) then
          if not furor_hud.shown[slot] then
            local layer, i = FurorHud_Slot(slot)
            furor_hud.shown[slot] = true
            furor_hud.fill[slot] = 0
            furor_hud.lit[slot] = true
            VRFW.host.menu_command(furor_hud.LAYER_VISIBLE, layer, i, true)
            if slot <= 2 then
              local x, y = FurorHud_Global(layer, i, furor_hud.DRAW_NODE)
              FurorHud_Log("shown", slot, "frame node at", string.format("%.1f %.1f", x or 0, y or 0))
            end
          end
          local frames = furor_hud.fill[slot] or 0
          furor_hud.fill[slot] = frames + 1
          if frames < Furor.hud.FILL_FRAMES or frames % Furor.hud.FILL_EVERY == 0 then
            FurorHud_Fill(slot)
          end
          FurorHud_Lit(slot, true)
          if look.alpha ~= nil then
            FurorHud_Alpha(slot, look.alpha)
          end
        end
      end
    end
  end
  FurorHud_Prompt()
end

-- Runs every frame of the match HUD.
-- VRFW hud:frame
VRFW.hud_frame = VRFW.hud_frame or {}
if UpdateScoreboardKeeperHp == nil or UpdateScoreboardKeeperHp ~= VRFW.hud_frame.wrapper then
  local previous = UpdateScoreboardKeeperHp
  local list = {}
  VRFW.hud_frame.subscribers = list
  --- Runs the previous frame hook, then every subscriber; answers the previous hook's results.
  VRFW.hud_frame.wrapper = function(...)
    local r = {n = 0}
    if type(previous) == "function" then
      r = table.pack(previous(...))
    end
    for i = 1, #list do
      pcall(list[i])
    end
    return table.unpack(r, 1, r.n)
  end
  UpdateScoreboardKeeperHp = VRFW.hud_frame.wrapper
  --- Adds f to the functions called every HUD frame.
  VRFW.hud_frame.on = function(f)
    if type(f) == "function" then
      VRFW.hud_frame.subscribers[#VRFW.hud_frame.subscribers + 1] = f
    end
  end
end
VRFW.hud_frame.on(function() FurorHud_Step() end)
-- The glyph's layer opens with the scoreboard.
if type(OnOpenSoccerConstantMenuLayer) == "function" then
  FurorHud_GameOpenLayer = OnOpenSoccerConstantMenuLayer
  OnOpenSoccerConstantMenuLayer = function(layer, index, ...)
    if layer == furor_hud.PROMPT.LAYER then
      pcall(FurorHud_PromptOpened)
    end
    return FurorHud_GameOpenLayer(layer, index, ...)
  end
end
-- ===== EVT Furor hud END =====
